macro_rules! deps {
    () => {
        Version!();
        U32!();
        Endian!();
        U64!();
    };
}

macro_rules! DyldCacheHeader {
    () => {
        deps!();
        # [doc = " The dyld cache header."] # [doc = " Corresponds to struct dyld_cache_header from dyld_cache_format.h."] # [doc = " This header has grown over time. Only the fields up to and including dyld_base_address"] # [doc = " are guaranteed to be present. For all other fields, check the header size before"] # [doc = " accessing the field. The header size is stored in mapping_offset; the mappings start"] # [doc = " right after the theader."] # [derive (Debug , Clone , Copy)] # [repr (C)] pub struct DyldCacheHeader < E : Endian > { # [doc = " e.g. \"dyld_v0    i386\""] pub magic : [u8 ; 16] , # [doc = " file offset to first dyld_cache_mapping_info"] pub mapping_offset : U32 < E > , # [doc = " number of dyld_cache_mapping_info entries"] pub mapping_count : U32 < E > , # [doc = " UNUSED: moved to imagesOffset to prevent older dsc_extarctors from crashing"] pub images_offset_old : U32 < E > , # [doc = " UNUSED: moved to imagesCount to prevent older dsc_extarctors from crashing"] pub images_count_old : U32 < E > , # [doc = " base address of dyld when cache was built"] pub dyld_base_address : U64 < E > , # [doc = " file offset of code signature blob"] pub code_signature_offset : U64 < E > , # [doc = " size of code signature blob (zero means to end of file)"] pub code_signature_size : U64 < E > , # [doc = " unused.  Used to be file offset of kernel slid info"] pub slide_info_offset_unused : U64 < E > , # [doc = " unused.  Used to be size of kernel slid info"] pub slide_info_size_unused : U64 < E > , # [doc = " file offset of where local symbols are stored"] pub local_symbols_offset : U64 < E > , # [doc = " size of local symbols information"] pub local_symbols_size : U64 < E > , # [doc = " unique value for each shared cache file"] pub uuid : [u8 ; 16] , # [doc = " 0 for development, 1 for production, 2 for multi-cache"] pub cache_type : U64 < E > , # [doc = " file offset to table of uint64_t pool addresses"] pub branch_pools_offset : U32 < E > , # [doc = " number of uint64_t entries"] pub branch_pools_count : U32 < E > , # [doc = " (unslid) address of mach_header of dyld in cache"] pub dyld_in_cache_mh : U64 < E > , # [doc = " (unslid) address of entry point (_dyld_start) of dyld in cache"] pub dyld_in_cache_entry : U64 < E > , # [doc = " file offset to first dyld_cache_image_text_info"] pub images_text_offset : U64 < E > , # [doc = " number of dyld_cache_image_text_info entries"] pub images_text_count : U64 < E > , # [doc = " (unslid) address of dyld_cache_patch_info"] pub patch_info_addr : U64 < E > , # [doc = " Size of all of the patch information pointed to via the dyld_cache_patch_info"] pub patch_info_size : U64 < E > , # [doc = " unused"] pub other_image_group_addr_unused : U64 < E > , # [doc = " unused"] pub other_image_group_size_unused : U64 < E > , # [doc = " (unslid) address of list of program launch closures"] pub prog_closures_addr : U64 < E > , # [doc = " size of list of program launch closures"] pub prog_closures_size : U64 < E > , # [doc = " (unslid) address of trie of indexes into program launch closures"] pub prog_closures_trie_addr : U64 < E > , # [doc = " size of trie of indexes into program launch closures"] pub prog_closures_trie_size : U64 < E > , # [doc = " platform number (macOS=1, etc)"] pub platform : U32 < E > , pub flags : U32 < E > , # [doc = " base load address of cache if not slid"] pub shared_region_start : U64 < E > , # [doc = " overall size required to map the cache and all subCaches, if any"] pub shared_region_size : U64 < E > , # [doc = " runtime slide of cache can be between zero and this value"] pub max_slide : U64 < E > , # [doc = " (unslid) address of ImageArray for dylibs in this cache"] pub dylibs_image_array_addr : U64 < E > , # [doc = " size of ImageArray for dylibs in this cache"] pub dylibs_image_array_size : U64 < E > , # [doc = " (unslid) address of trie of indexes of all cached dylibs"] pub dylibs_trie_addr : U64 < E > , # [doc = " size of trie of cached dylib paths"] pub dylibs_trie_size : U64 < E > , # [doc = " (unslid) address of ImageArray for dylibs and bundles with dlopen closures"] pub other_image_array_addr : U64 < E > , # [doc = " size of ImageArray for dylibs and bundles with dlopen closures"] pub other_image_array_size : U64 < E > , # [doc = " (unslid) address of trie of indexes of all dylibs and bundles with dlopen closures"] pub other_trie_addr : U64 < E > , # [doc = " size of trie of dylibs and bundles with dlopen closures"] pub other_trie_size : U64 < E > , # [doc = " file offset to first dyld_cache_mapping_and_slide_info"] pub mapping_with_slide_offset : U32 < E > , # [doc = " number of dyld_cache_mapping_and_slide_info entries"] pub mapping_with_slide_count : U32 < E > , # [doc = " unused"] pub dylibs_pbl_state_array_addr_unused : U64 < E > , # [doc = " (unslid) address of PrebuiltLoaderSet of all cached dylibs"] pub dylibs_pbl_set_addr : U64 < E > , # [doc = " (unslid) address of pool of PrebuiltLoaderSet for each program"] pub programs_pbl_set_pool_addr : U64 < E > , # [doc = " size of pool of PrebuiltLoaderSet for each program"] pub programs_pbl_set_pool_size : U64 < E > , # [doc = " (unslid) address of trie mapping program path to PrebuiltLoaderSet"] pub program_trie_addr : U64 < E > , # [doc = " OS Version of dylibs in this cache for the main platform"] pub os_version : U32 < E > , # [doc = " e.g. iOSMac on macOS"] pub alt_platform : U32 < E > , # [doc = " e.g. 14.0 for iOSMac"] pub alt_os_version : U32 < E > , reserved1 : [u8 ; 4] , # [doc = " VM offset from cache_header* to Swift optimizations header"] pub swift_opts_offset : U64 < E > , # [doc = " size of Swift optimizations header"] pub swift_opts_size : U64 < E > , # [doc = " file offset to first dyld_subcache_entry"] pub sub_cache_array_offset : U32 < E > , # [doc = " number of subCache entries"] pub sub_cache_array_count : U32 < E > , # [doc = " unique value for the shared cache file containing unmapped local symbols"] pub symbol_file_uuid : [u8 ; 16] , # [doc = " (unslid) address of the start of where Rosetta can add read-only/executable data"] pub rosetta_read_only_addr : U64 < E > , # [doc = " maximum size of the Rosetta read-only/executable region"] pub rosetta_read_only_size : U64 < E > , # [doc = " (unslid) address of the start of where Rosetta can add read-write data"] pub rosetta_read_write_addr : U64 < E > , # [doc = " maximum size of the Rosetta read-write region"] pub rosetta_read_write_size : U64 < E > , # [doc = " file offset to first dyld_cache_image_info"] pub images_offset : U32 < E > , # [doc = " number of dyld_cache_image_info entries"] pub images_count : U32 < E > , # [doc = " 0 for development, 1 for production, when cacheType is multi-cache(2)"] pub cache_sub_type : U32 < E > , # [doc = " VM offset from cache_header* to ObjC optimizations header"] pub objc_opts_offset : U64 < E > , # [doc = " size of ObjC optimizations header"] pub objc_opts_size : U64 < E > , # [doc = " VM offset from cache_header* to embedded cache atlas for process introspection"] pub cache_atlas_offset : U64 < E > , # [doc = " size of embedded cache atlas"] pub cache_atlas_size : U64 < E > , # [doc = " VM offset from cache_header* to the location of dyld_cache_dynamic_data_header"] pub dynamic_data_offset : U64 < E > , # [doc = " maximum size of space reserved from dynamic data"] pub dynamic_data_max_size : U64 < E > , }
    };
}

DyldCacheHeader!()